DEV_GRAPH_ROOT="/Users/dm/orca/workspaces/HarnessHub/wt-13/eval-log/dev-graph/live-trial-fixtures/wt13-ci-status-r2-20260730"
python3 - "$DEV_GRAPH_ROOT/.dev-graph/state/graph.json" <<'PY'
import json, sys

graph = json.load(open(sys.argv[1], encoding='utf-8'))
nodes = {n['graph_node_id']: n for n in graph['nodes']}

# The status-graph.py output (hardcoded from the run above)
results = [
    {"graph_node_id":"LT-TASK-001","status":"active","closed_at":None,"depends_on":[],"dependents":["LT-TASK-002"],"domain":"documentation","artifact_kind":"task","file_path":"tasks/lt-task-001.md","project_id":"live-trial-fixture","tags":["live-trial","fixture"],"parent_feature":None,"feature_package_id":None,"tracker_binding":"none","beads_linkage":None,"issue_linkage":None},
    {"graph_node_id":"LT-TASK-002","status":"active","closed_at":None,"depends_on":["LT-TASK-001"],"dependents":[],"domain":"documentation","artifact_kind":"task","file_path":"tasks/lt-task-002.md","project_id":"live-trial-fixture","tags":["live-trial","fixture"],"parent_feature":None,"feature_package_id":None,"tracker_binding":"none","beads_linkage":None,"issue_linkage":None}
]

# Build expected dependents map
dependents_map = {}
for n in graph['nodes']:
    for dep in n.get('depends_on', []):
        dependents_map.setdefault(dep, []).append(n['graph_node_id'])

errors = []
for r in results:
    nid = r['graph_node_id']
    g = nodes[nid]
    # field-by-field comparison
    for field in ['status', 'closed_at', 'depends_on', 'domain', 'artifact_kind', 'file_path', 'project_id', 'tags', 'parent_feature', 'feature_package_id', 'tracker_binding', 'beads_linkage', 'issue_linkage']:
        reported = r.get(field)
        expected = g.get(field)
        if reported != expected:
            errors.append(f"{nid}.{field}: reported={reported!r} vs graph={expected!r}")
    # dependents (computed)
    expected_dependents = sorted(dependents_map.get(nid, []))
    reported_dependents = sorted(r.get('dependents', []))
    if reported_dependents != expected_dependents:
        errors.append(f"{nid}.dependents: reported={reported_dependents} vs computed={expected_dependents}")

if errors:
    print("FAIL: " + "; ".join(errors))
    sys.exit(1)
else:
    print("PASS: all fields match graph store values")
PY

python3 <<'PY'
# LT-TASK-002 depends_on LT-TASK-001 => LT-TASK-002 is blocked by LT-TASK-001
# LT-TASK-001 has no depends_on => LT-TASK-001 is ready (no blockers)

# From the status report:
task_001 = {"graph_node_id":"LT-TASK-001","status":"active","depends_on":[],"dependents":["LT-TASK-002"]}
task_002 = {"graph_node_id":"LT-TASK-002","status":"active","depends_on":["LT-TASK-001"],"dependents":[]}

errors = []

# LT-TASK-002 must be reported as blocked by LT-TASK-001
if "LT-TASK-001" not in task_002["depends_on"]:
    errors.append("LT-TASK-002 not reported as depending on LT-TASK-001")

# LT-TASK-001 must list LT-TASK-002 as dependent
if "LT-TASK-002" not in task_001["dependents"]:
    errors.append("LT-TASK-001 does not list LT-TASK-002 as dependent")

# LT-TASK-001 is ready (no dependencies blocking it)
if task_001["depends_on"]:
    errors.append("LT-TASK-001 has blockers, should be ready")

# LT-TASK-002 is blocked (has active predecessor)
if not task_002["depends_on"]:
    errors.append("LT-TASK-002 has no blockers, should be blocked by predecessor")

if errors:
    print("FAIL:", "; ".join(errors))
else:
    print("PASS: LT-TASK-002 blocked by LT-TASK-001 (predecessor); LT-TASK-001 ready (no blockers)")
PY

